package com.example.starter.batch.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;
import java.util.List;

/**
 * 批次产率登记/修订请求。一个请求可含多批次：先校验最终分配，再单事务写入，
 * 任一失败整单回滚。yieldKey 为幂等键，指纹含操作者、expectedVersion、
 * 规范化批次集合和全部数值；同键成功重放首次快照，失败不占键。
 */
public record YieldSubmitRequest(
        @NotBlank(message = "yieldKey 不能为空") String yieldKey,
        @NotBlank(message = "operator 不能为空") String operator,
        @NotNull(message = "items 不能为空")
        @Size(min = 1, max = 20, message = "items 必须包含 1～20 个批次产率项")
        List<@Valid Item> items
) {

    /**
     * 单批次产率项。expectedVersion 为空表示首次登记；非空表示修订，须等于当前版本。
     * inputQty/outputQty 均须大于零且最多三位小数。
     */
    public record Item(
            @NotBlank(message = "batchKey 不能为空") String batchKey,
            @NotNull(message = "inputQty 不能为空") BigDecimal inputQty,
            @NotNull(message = "outputQty 不能为空") BigDecimal outputQty,
            Long expectedVersion
    ) {
    }
}

package com.example.starter.batch.dto;

import java.time.Instant;

/**
 * 单批次产率视图。inputQty/outputQty 为保留原始数值的十进制字符串（最多三位小数）；
 * yieldRate 为产出/投入按四位小数展示的字符串，仅用于展示，不回写存储。
 */
public record YieldRecordResponse(
        String batchKey,
        String inputQty,
        String outputQty,
        String yieldRate,
        long version,
        String operator,
        Instant createdAt,
        Instant updatedAt
) {
}

package com.example.starter.batch.dto;

import java.time.Instant;
import java.util.List;

/**
 * 产率登记/修订响应：本次落定的全部批次产率记录，按请求顺序返回。
 */
public record YieldSubmitResponse(
        String yieldKey,
        List<YieldRecordResponse> records,
        Instant submittedAt
) {
}

package com.example.starter.batch.dto;

import java.util.List;

/**
 * 批次父子分配汇总。数量为十进制字符串；未登记产率时对应字段为 null。
 * allocatedQty 为全部直接子批投入量之和；remainingQty = outputQty - allocatedQty。
 */
public record YieldAllocationResponse(
        String batchKey,
        String outputQty,
        String allocatedQty,
        String remainingQty,
        List<ChildAllocation> children,
        List<ParentAllocation> parents
) {

    /**
     * 直接子批的分配明细。
     */
    public record ChildAllocation(
            String batchKey,
            String inputQty,
            String outputQty,
            String yieldRate
    ) {
    }

    /**
     * 直接父批的分配汇总：父批产出、父批全部子批已分配投入、父批剩余可分配量，
     * 以及本批次占用的投入量（未登记产率时为 null）。
     */
    public record ParentAllocation(
            String parentKey,
            String parentOutputQty,
            String allocatedQty,
            String remainingQty,
            String thisInputQty
    ) {
    }
}

package com.example.starter.batch.dto;

import java.time.Instant;

/**
 * 产率召回阻断原因查询结果。blocked 为 true 时，recalledBatchKey 为阻断来源
 * （批次自身被直接召回，或血缘闭包内最近的被召回祖先），reason/recalledAt 为该召回记录。
 */
public record YieldBlockResponse(
        String batchKey,
        boolean blocked,
        String recalledBatchKey,
        String reason,
        Instant recalledAt
) {
}

