            String blocker = null;
            if (RECALLED.equals(batches.get(key).status())) blocker = key;
            else blocker = recalledAncestor(key, parentOf, recalled).orElse(null);
            if (blocker != null) throw conflict("批次 " + key + " 处于召回血缘闭包内（召回批次 " + blocker + "），不得新增或修订产率");
