if (out == null) {
    if (allocated.signum() > 0) throw unprocessable("父批次 " + P + " 未登记产出量，子批次不得登记投入量");
} else if (allocated.compareTo(out) > 0) {
    BigDecimal already = allocated.subtract(proposedForP);
    throw unprocessable("父批次 " + P + " 产出量 " + out.toPlainString() + " 不足：已分配 " + already.toPlainString() + "，拟分配 " + proposedForP.toPlainString());
