public YieldAllocationResponse getAllocation(String batchKey) {
    repo.findBatch(batchKey).orElseThrow(404);
    YieldRow self = repo.findYield(batchKey).orElse(null);
    List<ChildAllocation> children = new ArrayList<>();
    BigDecimal allocated = ZERO;
    for (String c : repo.findChildKeys(batchKey)) {
        YieldRow cy = repo.findYield(c).orElse(null);
        if (cy != null) { allocated = allocated.add(cy.inputQty()); children.add(new ChildAllocation(c, qty(cy.inputQty()), qty(cy.outputQty()), rate(cy))); }
        else children.add(new ChildAllocation(c, null, null, null));
    }
    String outputQty = self == null ? null : qty(self.outputQty());
    String remaining = self == null ? null : self.outputQty().subtract(allocated).toPlainString();
    List<ParentAllocation> parents = new ArrayList<>();
    for (String p : repo.findParentKeys(batchKey)) {
        YieldRow py = repo.findYield(p).orElse(null);
        BigDecimal pAlloc = sum of findChildYields(p) inputQty;
        parents.add(new ParentAllocation(p, py==null?null:qty(py.outputQty()), pAlloc.toPlainString(), py==null?null:py.outputQty().subtract(pAlloc).toPlainString(), self==null?null:qty(self.inputQty())));
    }
    return new YieldAllocationResponse(batchKey, outputQty, allocated.toPlainString(), remaining, children, parents);
}
