        submitYield(yieldBody("YK-D3", "op", List.of(item(b2, "1", "-0.5", null))), 400);
        // 三位小数边界 → 201，1/3 产率四位小数
        submitYield(yieldBody("YK-D4", "op", List.of(item(b2, "3", "1.001", null))), 201);
        JsonNode queried = getJson("/api/batches/" + b2 + "/yield", 200);
