    @Test
    void reviseYield_expectedVersionRules() throws Exception {
        String batch = "BK-Y-V-" + unique();
        createBatch(batch);
        submitYield(yieldBody("YK-V1", "op-1", List.of(item(batch, "10", "9", null))), 201);

