        submitYield(yieldBody("YK-V2", "op-1", List.of(item(batch, "10", "8", null))), 409);
        // 版本不匹配 → 409
        submitYield(yieldBody("YK-V3", "op-1", List.of(item(batch, "10", "8", 5L))), 409);
